content:
#!/bin/sh
# PreToolUse hook (Bash): blocks rm invocations that combine recursive and force
# flags - rm -rf, rm -fr, rm -Rf, rm -r -f, rm --recursive --force - including
# when they appear after && / ; / | or inside $(...) and backticks.
# Reads the event JSON on stdin. Exit 2 blocks the call and sends stderr to Claude.
# Registered with "onFailure": "block", so a missing python3 also blocks.
CHECK=$(cat <<'PY'
import json
import os
import shlex
import sys

SEPARATORS = set(";&|()<>")


def is_separator(token):
    return bool(token) and all(c in SEPARATORS for c in token)


def recursive_and_force(args):
    recursive = force = False
    for arg in args:
        if arg == "--":
            break
        if arg == "--recursive":
            recursive = True
        elif arg == "--force":
            force = True
        elif arg.startswith("-") and not arg.startswith("--"):
            recursive = recursive or any(c in "rR" for c in arg[1:])
            force = force or "f" in arg[1:]
    return recursive and force


def blocked(command):
    # Substitutions start a new command, so treat them as separators.
    text = command.replace("`", " ; ").replace("$(", " ; ")
    lexer = shlex.shlex(text, posix=True, punctuation_chars=True)
    lexer.whitespace_split = True
    tokens = list(lexer)
    for i, token in enumerate(tokens):
        if os.path.basename(token) != "rm":
            continue
        args = []
        for arg in tokens[i + 1:]:
            if is_separator(arg):
                break
            args.append(arg)
        if recursive_and_force(args):
            return True
    return False


try:
    event = json.load(sys.stdin)
    command = (event.get("tool_input") or {}).get("command") or ""
    is_blocked = blocked(command)
except Exception:
    print("block-rm: could not parse the Bash command; blocking to be safe.", file=sys.stderr)
    sys.exit(2)

if is_blocked:
    print(
        "Blocked by the block-rm hook: rm -rf (recursive + force) is not allowed in this "
        "project. Delete named files individually, or ask the user to run the command.",
        file=sys.stderr,
    )
    sys.exit(2)
PY
)
exec python3 -I -c "$CHECK"

