Register this route before any global `express.json()` middleware. Stripe's signature is computed over the exact raw bytes, so the route needs `express.raw()` to get an unparsed `Buffer`.

```js
const express = require('express');
const Stripe = require('stripe');

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

const app = express();

// Raw body for signature verification. Must come before any express.json() that
// would also match this route.
app.post(
  '/webhooks/stripe',
  express.raw({ type: 'application/json' }),
  (req, res) => {
    let event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        req.headers['stripe-signature'],
        webhookSecret
      );
    } catch (err) {
      console.warn('Stripe webhook signature verification failed:', err.message);
      return res.status(400).send('Invalid signature');
    }

    if (event.type === 'payment_intent.succeeded') {
      const paymentIntent = event.data.object;

      // Log identifiers and amounts only. The full object can contain PII.
      console.log(JSON.stringify({
        msg: 'payment_intent.succeeded',
        eventId: event.id,
        paymentIntentId: paymentIntent.id,
        amount: paymentIntent.amount,
        currency: paymentIntent.currency,
        created: new Date(event.created * 1000).toISOString(),
      }));
    }

    // Acknowledge every event, including ones you don't handle, so Stripe doesn't retry them.
    res.json({ received: true });
  }
);

app.use(express.json()); // other routes

app.listen(3000);
```

Notes:

- **Signature check:** `constructEvent` throws if the signature is missing, malformed, doesn't match, or is older than the default 5-minute tolerance. The handler returns 400 and doesn't echo the error details.
- **Secret:** `STRIPE_WEBHOOK_SECRET` is the `whsec_...` value for this endpoint. It's different from your API secret key. For local testing it comes from `stripe listen`.
- **Retries:** Stripe retries on non-2xx responses and can deliver the same event more than once. If you need exactly-once logging, dedupe on `event.id`.
- **ESM:** If you use `import`, write `import Stripe from 'stripe'` and `import express from 'express'`. The handler is the same.

