#!/bin/sh
# Stop gate: block Claude from finishing while `npm test` fails.
# Exit 2 blocks the stop; stderr is the instruction Claude gets next.

cd "${CLAUDE_PROJECT_DIR:-.}" || exit 2

# The event payload is not needed; drain stdin so the harness write never blocks.
cat >/dev/null

# Nothing to gate on outside a Node project.
[ -f package.json ] || exit 0

output=$(npm test 2>&1)
status=$?
if [ "$status" -eq 0 ]; then
  exit 0
fi

{
  echo "Stop blocked: \`npm test\` is failing (exit $status). Fix the failures, run \`npm test\` until it passes, then finish."
  echo
  printf '%s\n' "$output" | tail -n 80
} >&2
exit 2
EOF
